const now = new Date().toISOString();

function update(name, datatype, value) {
    return {
        payload: {
            messageType: "Variable",
            namespace: 1,
            // node-red-contrib-opcua 0.2.244 indexa las variables como "ns:nombre".
            variableName: "1:" + name,
            datatype: datatype,
            variableValue: value
        }
    };
}

// El nodo OpcUa-Server no tolera addVariable repetido y su deleteNode falla
// cuando findNode devuelve null. Si este servidor ya fue inicializado, no se
// reconstruye: solamente se restauran los valores de seguridad.
if (flow.get("vfdAddressSpaceReady") === true) {
    let current = flow.get("vfdState") || {};
    current.frequencySetpointHz = 0.0;
    current.frequencyRaw = 0;
    current.motorCommand = 5;
    current.requestedState = "STOPPED";
    current.commandValid = true;
    current.lastWebAction = "SAFE_REINITIALIZATION";
    current.lastWebUpdate = now;
    flow.set("vfdState", current);

    return [[
        update("FrequencySetpointHz", "Double", 0.0),
        update("FrequencyRaw", "UInt16", 0),
        update("MotorCommand", "UInt16", 5),
        update("RequestedState", "String", "STOPPED"),
        update("CommandValid", "Boolean", true)
    ], {
        payload: {
            level: "info",
            event: "ADDRESS_SPACE_ALREADY_READY_SAFE_RESET",
            timestamp: now,
            safeCommand: 5,
            safeFrequencyHz: 0.0
        }
    }];
}

const state = {
    frequencySetpointHz: 0.0,
    frequencyRaw: 0,
    motorCommand: 5,
    requestedState: "STOPPED",
    commandSequence: 0,
    commandValid: true,
    webHeartbeat: 0,
    webOnline: true,
    twinCATOnline: false,
    twinCATSession: "NO_SESSION",
    plcFrequencyRawAck: 0,
    plcCommandAck: 5,
    vfdRunning: false,
    vfdFault: false,
    vfdStatusText: "NO_FEEDBACK",
    lastWriteOk: false,
    lastWriteStatus: "WAITING_TWINCAT",
    lastWriteTimestamp: "NONE",
    lastWebAction: "SAFE_INITIALIZATION",
    lastWebUpdate: now,
    serverStatus: "INITIALIZING",
    endpoint: "opc.tcp://172.28.76.226:53881/UA/VFDGateway"
};

flow.set("vfdState", state);

function command(topic, opcuaCommand) {
    return { topic: topic, payload: { opcuaCommand: opcuaCommand } };
}

function variable(name, datatype, value, description) {
    return command(
        "ns=1;s=" + name +
        ";datatype=" + datatype +
        ";description=" + description +
        ";value=" + String(value),
        "addVariable"
    );
}

const commands = [
    // Fijar Objects como padre antes de crear la carpeta de la aplicación.
    command("ns=0;i=85", "setFolder"),
    command("ns=1;s=VFD_Gateway;description=Gateway OPC UA para TwinCAT y PLC Delta", "addFolder"),
    command("ns=1;s=VFD_Gateway", "setFolder"),

    variable("FrequencySetpointHz", "Double", 0.0, "Consigna web de frecuencia de 0 a 60 Hz"),
    variable("FrequencyRaw", "UInt16", 0, "Consigna escalada de 0 a 10000"),
    variable("MotorCommand", "UInt16", 5, "Comando de motor 1 ARRANQUE 5 PARADA"),
    variable("RequestedState", "String", "STOPPED", "Estado solicitado desde la web"),
    variable("CommandSequence", "UInt32", 0, "Secuencia monotona de ordenes web"),
    variable("CommandValid", "Boolean", true, "Resultado de validacion de la ultima orden"),

    variable("FrequencyRegister", "UInt16", 4096, "Direccion Modbus del VFD para frecuencia"),
    variable("CommandRegister", "UInt16", 8192, "Direccion Modbus del VFD para marcha y parada"),
    variable("ScaleMaxHz", "Double", 60.0, "Escala maxima de frecuencia"),
    variable("ScaleMaxRaw", "UInt16", 10000, "Escala maxima del registro del VFD"),

    variable("WebHeartbeat", "UInt32", 0, "Heartbeat del servidor web Node RED"),
    variable("WebOnline", "Boolean", true, "Estado del servidor web Node RED"),
    variable("TwinCATOnline", "Boolean", false, "Confirmacion escrita desde TwinCAT"),

    variable("LastWriteOk", "Boolean", false, "Confirmacion final de la transaccion PLC VFD"),
    variable("LastWriteStatus", "String", "WAITING_TWINCAT", "Estado de la ultima transaccion"),
    variable("LastWriteTimestamp", "String", "NONE", "Fecha de la ultima confirmacion"),
    variable("PlcFrequencyRawAck", "UInt16", 0, "Eco de frecuencia recibido desde el PLC"),
    variable("PlcCommandAck", "UInt16", 5, "Eco de comando recibido desde el PLC"),
    variable("VfdRunning", "Boolean", false, "Realimentacion de marcha del variador"),
    variable("VfdFault", "Boolean", false, "Realimentacion de falla del variador"),
    variable("VfdStatusText", "String", "NO_FEEDBACK", "Diagnostico escrito desde TwinCAT o PLC")
];

flow.set("vfdAddressSpaceReady", true);

const audit = {
    payload: {
        level: "info",
        event: "ADDRESS_SPACE_BUILD_REQUESTED",
        timestamp: now,
        endpoint: state.endpoint,
        safeCommand: 5,
        safeFrequencyHz: 0.0
    }
};

return [commands, audit];

let state = flow.get("vfdState");
if (!state) {
    return null;
}

const p = msg.payload;

if (msg.topic === "Client-connected") {
    state.twinCATSession = String(p || "OPC_UA_CLIENT");
    state.twinCATOnline = true;
} else if (msg.topic === "Client-disconnected") {
    state.twinCATSession = "NO_SESSION";
    state.twinCATOnline = false;
}

if (p && typeof p === "object" && p.messageType === "Variable" &&
    Object.prototype.hasOwnProperty.call(p, "variableValue")) {
    const name = String(p.variableName || "").replace(/^\d+:/, "");
    const value = p.variableValue;

    switch (name) {
        case "FrequencySetpointHz": state.frequencySetpointHz = Number(value); break;
        case "FrequencyRaw": state.frequencyRaw = Number(value); break;
        case "MotorCommand": state.motorCommand = Number(value); break;
        case "RequestedState": state.requestedState = String(value); break;
        case "CommandSequence": state.commandSequence = Number(value); break;
        case "CommandValid": state.commandValid = Boolean(value); break;
        case "WebHeartbeat": state.webHeartbeat = Number(value); break;
        case "WebOnline": state.webOnline = Boolean(value); break;
        case "TwinCATOnline": state.twinCATOnline = Boolean(value); break;
        case "LastWriteOk": state.lastWriteOk = Boolean(value); break;
        case "LastWriteStatus": state.lastWriteStatus = String(value); break;
        case "LastWriteTimestamp": state.lastWriteTimestamp = String(value); break;
        case "PlcFrequencyRawAck": state.plcFrequencyRawAck = Number(value); break;
        case "PlcCommandAck": state.plcCommandAck = Number(value); break;
        case "VfdRunning": state.vfdRunning = Boolean(value); break;
        case "VfdFault": state.vfdFault = Boolean(value); break;
        case "VfdStatusText": state.vfdStatusText = String(value); break;
        default: break;
    }
}

flow.set("vfdState", state);
return { payload: { event: "OPCUA_SERVER_OUTPUT", topic: msg.topic || "", timestamp: new Date().toISOString() } };

let state = flow.get("vfdState");
const status = msg.status || {};
let serverStatus = String(status.text || "UNKNOWN").toUpperCase();
if (serverStatus.indexOf("RUNNING") >= 0) {
    serverStatus = "RUNNING";
    // Un nuevo address space comienza vacío. El inject de 5 s lo construirá.
    flow.set("vfdAddressSpaceReady", false);
}
if (state) {
    state.serverStatus = serverStatus;
    flow.set("vfdState", state);
}
return { payload: { event: "SERVER_STATUS", status: serverStatus } };

let state = flow.get("vfdState");
if (state) {
    state.serverStatus = "ERROR";
    state.lastWriteOk = false;
    state.lastWriteStatus = "OPCUA_SERVER_ERROR";
    flow.set("vfdState", state);
}

const detail = msg.error && msg.error.message ? msg.error.message : "Unknown OPC UA error";
return [
    { payload: { event: "SERVER_ERROR", detail: detail } },
    { payload: { level: "error", event: "SERVER_ERROR", detail: detail, timestamp: new Date().toISOString() } }
];

let state = flow.get("vfdState");
if (!state) {
    return null;
}

state.webHeartbeat = (Number(state.webHeartbeat || 0) + 1) >>> 0;
state.webOnline = true;
flow.set("vfdState", state);

function ua(name, datatype, value) {
    return {
        payload: {
            messageType: "Variable",
            namespace: 1,
            // El servidor 0.2.244 requiere el prefijo del namespace para actualizar.
            variableName: "1:" + name,
            datatype: datatype,
            variableValue: value
        }
    };
}

return [[
    ua("WebHeartbeat", "UInt32", state.webHeartbeat),
    ua("WebOnline", "Boolean", true)
], { payload: { event: "HEARTBEAT", value: state.webHeartbeat } }];

const p = msg.payload || {};
let state = flow.get("vfdState");

if (!state) {
    node.error("El estado VFD no ha sido inicializado", msg);
    return [null, { payload: { level: "error", event: "STATE_NOT_INITIALIZED" } }];
}

const now = new Date().toISOString();

function ua(name, datatype, value) {
    return {
        payload: {
            messageType: "Variable",
            namespace: 1,
            // El servidor 0.2.244 requiere el prefijo del namespace para actualizar.
            variableName: "1:" + name,
            datatype: datatype,
            variableValue: value
        }
    };
}

function reject(reason) {
    state.commandValid = false;
    state.lastWebAction = "REJECTED: " + reason;
    state.lastWebUpdate = now;
    flow.set("vfdState", state);
    return [
        ua("CommandValid", "Boolean", false),
        ua("LastWriteOk", "Boolean", false),
        ua("LastWriteStatus", "String", "WEB_REJECTED_" + reason.replace(/\s+/g, "_"))
    ];
}

let updates = [];
let event = String(p.action || "").toLowerCase();
let accepted = true;
let detail = "";

if (event === "apply_frequency") {
    let hz = Number(p.value);
    if (!Number.isFinite(hz) || hz < 0 || hz > 60) {
        accepted = false;
        detail = "FREQUENCY_OUT_OF_RANGE";
        updates = reject(detail);
    } else {
        hz = Math.round(hz * 10) / 10;
        const raw = Math.round(hz * 10000 / 60);
        state.frequencySetpointHz = hz;
        state.frequencyRaw = raw;
        state.lastWebAction = "APPLY_FREQUENCY";
        detail = hz.toFixed(1) + " Hz -> " + raw;
        updates.push(ua("FrequencySetpointHz", "Double", hz));
        updates.push(ua("FrequencyRaw", "UInt16", raw));
    }
} else if (event === "start") {
    state.motorCommand = 1;
    state.requestedState = "START_REQUESTED";
    state.lastWebAction = "START_REQUESTED";
    detail = "MotorCommand=1";
    updates.push(ua("MotorCommand", "UInt16", 1));
    updates.push(ua("RequestedState", "String", state.requestedState));
} else if (event === "stop") {
    state.motorCommand = 5;
    state.requestedState = "STOP_REQUESTED";
    state.lastWebAction = "STOP_REQUESTED";
    detail = "MotorCommand=5";
    updates.push(ua("MotorCommand", "UInt16", 5));
    updates.push(ua("RequestedState", "String", state.requestedState));
} else if (event === "safe_stop") {
    state.frequencySetpointHz = 0.0;
    state.frequencyRaw = 0;
    state.motorCommand = 5;
    state.requestedState = "SAFE_STOP_REQUESTED";
    state.lastWebAction = "SAFE_STOP_REQUESTED";
    detail = "0 Hz and MotorCommand=5";
    updates.push(ua("FrequencySetpointHz", "Double", 0.0));
    updates.push(ua("FrequencyRaw", "UInt16", 0));
    updates.push(ua("MotorCommand", "UInt16", 5));
    updates.push(ua("RequestedState", "String", state.requestedState));
} else {
    accepted = false;
    detail = "UNKNOWN_ACTION";
    updates = reject(detail);
}

if (accepted) {
    state.commandSequence = (Number(state.commandSequence || 0) + 1) >>> 0;
    state.commandValid = true;
    state.lastWriteOk = false;
    state.lastWriteStatus = "PENDING_TWINCAT";
    state.lastWebUpdate = now;
    updates.push(ua("CommandSequence", "UInt32", state.commandSequence));
    updates.push(ua("CommandValid", "Boolean", true));
    updates.push(ua("LastWriteOk", "Boolean", false));
    updates.push(ua("LastWriteStatus", "String", "PENDING_TWINCAT"));
}

flow.set("vfdState", state);

const audit = {
    payload: {
        level: accepted ? "info" : "error",
        event: event || "unknown",
        accepted: accepted,
        detail: detail,
        sequence: state.commandSequence,
        timestamp: now
    }
};

return [updates, audit];
